# His Club packs: Hull City, Ipswich Town, Leeds United, Liverpool, Manchester City. Rewritten 2026-09-08.
# (difficulty, question, options, answer_index, explanation, useType, use)

HULL = [
    (1, "What is Hull City's nickname?", ["The Tigers", "The Lions", "The Codheads"], 0,
     "The Tigers, a name from the club's first years. Commentators use it as often as the club's real name.",
     "say", "\"The Tigers. Easy one to remember.\""),
    (1, "What is Hull City's home ground called?", ["MKM Stadium", "Kingston Park", "Craven Park"], 0,
     "The MKM Stadium, since 2002, shared with the rugby league club Hull FC. It opened as the KC Stadium; sponsors change, the building doesn't.",
     "say", "\"The MKM. Used to be the KC. Same place.\""),
    (1, "What colours are Hull's home shirts?", ["Amber and black", "Red and white", "Blue and white"], 0,
     "Amber and black stripes, worn since the club's earliest days.",
     "say", "\"Amber and black. That's Hull.\""),
    (2, "In which year was Hull City founded?", ["1888", "1904", "1919"], 1,
     "1904. Hull was a rugby league city and the football club took decades to catch on. It took them 104 years to reach the top division.",
     "impress", "\"Hull's a rugby city. The football club took a hundred and four years to reach the top flight.\""),
    (3, "Which club did Hull beat at Wembley in the 2008 play-off final?", ["Bristol City", "Watford", "Crystal Palace"], 0,
     "Bristol City, 1-0, in front of about 86,000. It took Hull into the top division for the first time in their history.",
     "ask", "\"Where were you for the 2008 play-off final?\""),
    (3, "Who scored the winning goal in Hull's 2008 play-off final?", ["Dean Windass", "Nick Barmby", "Ian Ashbee"], 0,
     "Dean Windass, a 39-year-old born in Hull who had been released by the club as a teenager, with a volley from the edge of the box. He wept on the pitch.",
     "impress", "\"The winner in 2008 was scored by a 39-year-old from Hull who the club had released as a teenager.\""),
    (2, "Which manager took Hull into the Premier League in 2008?", ["Phil Brown", "Steve Bruce", "Peter Taylor"], 0,
     "Phil Brown, remembered for his suntan, his headset and one very public team talk. He sang to the fans on the pitch when they stayed up.",
     "say", "\"Phil Brown. The one with the tan and the headset.\""),
    (3, "In 2008 Hull's manager gave a half-time team talk on the pitch. At which club's ground?", ['Manchester City', 'Manchester United', 'Chelsea'], 0,
     "Manchester City's, on Boxing Day, 4-0 down at the break. He sat the players on the grass and lectured them. It finished 5-1; later he said he'd change nothing.",
     'impress', '"Hull\'s manager once did the half-time team talk on the pitch, in front of the fans. Sat them all down. They lost 5-1."'),
    (2, "Hull reached the FA Cup final in 2014 and lost to which club?", ["Arsenal", "Chelsea", "Liverpool"], 0,
     "Arsenal, 3-2 after extra time, and Hull had led 2-0 inside eight minutes. It was the club's first FA Cup final.",
     "ask", "\"2014, two-nil up at Wembley after eight minutes. Do you ever think about it?\""),
    (2, "Who managed Hull in the 2014 FA Cup final?", ["Steve Bruce", "Phil Brown", "Nigel Adkins"], 0,
     "Steve Bruce, the former Manchester United captain. Because the winners were already in the Champions League, losing the final put Hull into Europe for the first time.",
     "impress", "\"Hull got into Europe by losing a cup final. The winners were already qualified.\""),
    (3, "In 2013 Hull's owners tried to rename the club. The FA refused. What did they want to drop?", ["The word 'City'", "The letters 'AFC'", "The word 'Hull'"], 0,
     "'City'. The owners called the word common. Fans marched, the FA said no, and the row with the owners ran on for years.",
     'ask', '"Were you part of the protests when the owners tried to take \'City\' out of the name?"'),
    (2, "What was Hull's home ground before 2002?", ["Boothferry Park", "Craven Park", "Anlaby Road"], 0,
     "Boothferry Park, from 1946, which had its own railway station and, by the end, a supermarket built into one stand.",
     "impress", "\"Hull's old ground had a supermarket built into one of the stands. Boothferry Park.\""),
    (1, "Hull is in which historic county?", ["Yorkshire", "Lincolnshire", "Lancashire"], 0,
     "Yorkshire, the East Riding. The city's full name is Kingston upon Hull, and it sits where the River Hull meets the Humber.",
     "say", "\"Hull's Yorkshire. East Riding, on the Humber.\""),
    (2, "Which club do Hull fans regard as their main rivals?", ["Leeds United", "Stoke City", "Norwich City"], 0,
     "Leeds United, the big club sixty miles west. Grimsby, over the Humber, is the older, smaller grudge.",
     "say", "\"Hull and Leeds. Two cities, one long grudge.\""),
    (3, "Which Portuguese manager led Hull in the Premier League in 2016-17?", ["Marco Silva", "Paulo Fonseca", "Carlos Carvalhal"], 0,
     "Marco Silva, in his first English job. Hull went down anyway, but his reputation survived and he went on to manage Watford, Everton and Fulham.",
     "say", "\"Marco Silva started in England at Hull. Didn't keep them up, but everyone noticed him.\""),
    (3, "After relegation from the Premier League in 2017, Hull dropped to League One in which year?", ["2019", "2020", "2021"], 1,
     "2020, finishing bottom of the Championship in the pandemic season. Two relegations in three years.",
     "ask", "\"How bad was the League One year? Did you keep going?\""),
    (3, "Who managed Hull to the League One title?", ["Grant McCann", "Nigel Adkins", "Liam Rosenior"], 0,
     "Grant McCann, a Northern Irish former midfielder, who took them up as champions at the first attempt.",
     "say", "\"Grant McCann took them straight back up as champions. Didn't hang about.\""),
    (3, "Which Turkish television personality bought Hull City in 2022?", ["Acun Ilıcalı", "Fatih Terim", "Cem Yılmaz"], 0,
     "Acun Ilıcalı, the face of Turkey's version of Survivor, who built his own TV network. He promised the Premier League and, in the end, delivered it.",
     "impress", "\"Hull were bought by the man behind Survivor in Turkey. Basically Turkish Ant and Dec.\""),
    (2, "In which year did Hull return to the Premier League for the first time since 2017?", ["2024", "2025", "2026"], 2,
     "2026, through the play-offs after finishing sixth in the Championship. Nine years away, including one in the third tier.",
     "ask", "\"Where were you when they went up through the play-offs this time?\""),
    (2, "What is Hull City's mascot called?", ['Humber', 'Roary', 'Stripes'], 1,
     'Roary, a tiger in the club kit, who works the touchline before kick-off and at half-time.',
     'say', '"Roary. Of course the tiger\'s called Roary."'),
]

IPSWICH = [
    (1, "What is Ipswich Town's home ground called?", ["Portman Road", "Carrow Road", "Layer Road"], 0,
     "Portman Road, the club's home since 1884, a short walk from the town centre and the railway station.",
     "say", "\"Portman Road. They've played there since 1884.\""),
    (1, "What is Ipswich Town's nickname?", ["The Tractor Boys", "The Canaries", "The Farmers"], 0,
     "The Tractor Boys. Rival fans meant it as a jibe about the farming county around the town; Ipswich fans adopted it and put it on scarves.",
     "say", "\"Tractor Boys started as an insult. Ipswich just took it and ran.\""),
    (2, 'Ipswich beat Norwich 3-1 in October 2025. It was their first derby win in how many years?', ['Six', 'Sixteen', 'Twenty-six'], 1,
     'Sixteen. They won at Carrow Road in April 2026 too, their first league double over Norwich since 1992-93.',
     'ask', '"Sixteen years without beating Norwich. How good was that season?"'),
    (2, "In which year was Ipswich Town founded?", ["1878", "1888", "1898"], 0,
     "1878, though they stayed amateur until 1936 and joined the Football League in 1938. Late starters who then went all the way to the top.",
     "impress", "\"Ipswich were amateurs until 1936. Within a generation they were champions of England.\""),
    (2, "In which year did Ipswich win the league title?", ["1962", "1972", "1982"], 0,
     "1962, in their very first season in the top division, a year after winning the second tier.",
     "impress", "\"Ipswich won the title in their first ever season in the top division. 1962.\""),
    (2, "Which future England manager took Ipswich from the third tier to league champions?", ["Alf Ramsey", "Don Revie", "Graham Taylor"], 0,
     "Alf Ramsey, who arrived in 1955 with the club in the third tier and went on to win the World Championship with England. His statue stands outside the ground.",
     "impress", "\"Alf Ramsey made England world champions in 1966. He learned how at Ipswich.\""),
    (2, "In which year did Ipswich win the FA Cup?", ["1968", "1978", "1988"], 1,
     "1978, beating Arsenal 1-0 at Wembley. The scorer was so overcome he had to be substituted straight afterwards.",
     "impress", "\"The guy who scored Ipswich's cup final winner had to come off straight after. Overcome.\""),
    (2, "Which European trophy did Ipswich win in 1981?", ["The UEFA Cup", "The Cup Winners' Cup", "The European Cup"], 0,
     "The UEFA Cup, over a two-legged final, 5-4 on aggregate, with a side that played lovely football.",
     "impress", "\"Ipswich won a European trophy in 1981. And it's a town, not even a city.\""),
    (2, "Which manager led Ipswich from 1969 to 1982, then took the England job?", ["Bobby Robson", "George Burley", "Joe Royle"], 0,
     "Bobby Robson, who went on to manage England, Barcelona and Newcastle. His statue stands outside the ground.",
     "say", "\"Bobby Robson learned his trade at Ipswich. Thirteen years before England.\""),
    (2, "Which Northern Irish manager took Ipswich from League One to the Premier League in 2023 and 2024?", ["Kieran McKenna", "Brendan Rodgers", "Martin O'Neill"], 0,
     "Kieran McKenna, back-to-back promotions in his first two full seasons, after 22 years out of the top flight. Big clubs came calling and he stayed.",
     "say", "\"McKenna took them from the third tier to the Premier League in two seasons.\""),
    (3, "Who did Ipswich beat in their 1981 European final?", ["AZ Alkmaar", "Feyenoord", "Cologne"], 0,
     "AZ Alkmaar, 3-0 at home and 2-4 away. John Wark, a midfielder, scored 14 goals in the competition that season.",
     "impress", "\"They beat AZ Alkmaar in the 1981 final. Their midfielder scored fourteen European goals that year.\""),
    (1, "What colours are Ipswich Town's home shirts?", ["Blue and white", "Yellow and green", "Red and white"], 0,
     "Blue shirts and white shorts. Norwich are yellow and green, which makes the derby easy to follow.",
     "say", "\"Blue and white is Ipswich. Yellow and green is Norwich. Two different worlds.\""),
    (3, 'Who scored the winner when Ipswich beat Arsenal in an FA Cup final?', ['Roger Osborne', 'Paul Mariner', 'Kevin Beattie'], 0,
     'Roger Osborne, a local lad, in the 77th minute. He collapsed with emotion and exhaustion and was substituted moments later.',
     'say', '"Roger Osborne. Scored the cup final winner and had to be taken off in tears."'),
    (1, "Ipswich is in which county?", ["Suffolk", "Norfolk", "Essex"], 0,
     "Suffolk, on the east coast. Norwich, in Norfolk, is forty miles north and the source of all the trouble.",
     "say", "\"Suffolk. Norwich are Norfolk. That's the whole derby.\""),
    (2, "What animal is on the Ipswich Town badge?", ["A bull", "A horse", "A lion"], 1,
     "A carthorse, the county's own heavy farm breed. Norwich have a canary; Ipswich chose a horse.",
     "say", "\"It's a farm horse on the badge. They lean into it.\""),
    (3, "Ipswich were founder members of the Premier League in which season?", ["1992-93", "1994-95", "1996-97"], 0,
     "1992-93, having won the second tier the previous year. They were relegated in 1995 after a 9-0 defeat at Manchester United.",
     "impress", "\"Ipswich were in the very first Premier League season. Then lost 9-0 at Old Trafford and went down.\""),
    (3, "Where did Ipswich finish in 2000-01, their first Premier League season back up?", ["Third", "Fifth", "Seventh"], 1,
     "Fifth, under George Burley, which took them into Europe. Burley was voted manager of the year.",
     "say", "\"They finished fifth in 2001. Above Chelsea. Different times.\""),
    (3, "What tongue-in-cheek name is given to the Ipswich v Norwich derby?", ["The Old Farm derby", "The Turnip derby", "The Broads derby"], 0,
     "The Old Farm derby, a joke on the Old Firm, Glasgow's Celtic against Rangers. Both sets of fans use it.",
     "say", "\"Old Farm derby. Even the fans call it that.\""),
    (2, "Ipswich went straight back down in 2025. Which two clubs went down with them?", ["Leicester and Southampton", "Sheffield United and Luton", "Watford and Norwich"], 0,
     "Leicester and Southampton, the other two promoted clubs. It was the second season running that all three promoted sides went straight back down.",
     "ask", "\"Was going down in 2025 worse because of how good 2024 had felt?\""),
    (2, "How did Ipswich win promotion back to the Premier League in 2026?", ["Finishing second", "Winning the play-offs", "Winning the Championship"], 0,
     "Second in the Championship, behind Coventry, which means automatic promotion with no play-offs. One season down, straight back up.",
     "say", "\"Second in the Championship. Straight back up, no play-offs needed.\""),
]

LEEDS = [
    (1, "What is Leeds United's home ground called?", ["Elland Road", "Headingley", "Roundhay Park"], 0,
     "Elland Road, famous for being loud and hostile to visitors. Leeds fans consider that a compliment.",
     "say", "\"Elland Road on a night game. Properly hostile.\""),
    (1, "What colour do Leeds United play in?", ["All white", "Blue and white", "White and green"], 0,
     "All white, shirts, shorts and socks, since 1961. Before that Leeds wore blue and gold.",
     "say", "\"All white. Shirts, shorts, socks. That's Leeds.\""),
    (2, "In which year was Leeds United founded?", ["1904", "1919", "1925"], 1,
     "1919, after the previous club, Leeds City, was expelled from the league for illegal payments to players. A fresh start with a new name.",
     "impress", "\"Leeds United only exist because the old club got kicked out of the league for paying players illegally.\""),
    (2, "Which manager built the great Leeds team of the 1960s and 70s?", ["Don Revie", "Brian Clough", "Jimmy Armfield"], 0,
     "Don Revie, manager 1961 to 1974: two league titles, an FA Cup and a reputation for being brilliant, ruthless and hard to like. Left to manage England.",
     "ask", "\"Was Revie's Leeds dirty, or just better than everyone and hated for it?\""),
    (2, "In which year did Leeds win the league title, the third in the club's history?", ["1974", "1992", "2001"], 1,
     "1992, the final season before the Premier League began. Three titles in total: 1969, 1974 and 1992.",
     "say", "\"Leeds were the champions the year before the Premier League started. They like reminding people.\""),
    (2, 'Who managed Leeds to their third league title?', ['Howard Wilkinson', "David O'Leary", 'George Graham'], 0,
     'Howard Wilkinson, known as Sergeant Wilko. By 2026 no English manager had won the top division since.',
     'ask', '"Is it true no English manager has won the league since Howard Wilkinson?"'),
    (2, "In which year did Leeds reach the semi-finals of the Champions League?", ["1975", "1992", "2001"], 2,
     "2001, losing to Valencia, with a young team that had beaten Deportivo and drawn with Barcelona. Then the money ran out.",
     "ask", "\"Do you remember the 2001 Champions League team? Before it all went wrong?\""),
    (3, "By which year had Leeds fallen to League One, the third tier, after their financial collapse?", ["2004", "2007", "2010"], 1,
     "2007, three years after leaving the Premier League. They had spent money they expected from the Champions League and it stopped coming. The phrase is 'doing a Leeds'.",
     "impress", "\"'Doing a Leeds' means spending money you haven't got. They went from a Champions League semi to the third tier in a few years.\""),
    (2, "Which Argentine manager took Leeds back to the Premier League in 2020?", ["Marcelo Bielsa", "Diego Simeone", "Jorge Sampaoli"], 0,
     "Marcelo Bielsa, who sat on a blue bucket, ran the players into the ground and was adored. He ended sixteen years out of the top flight.",
     "ask", "\"Bielsa: greatest thing that ever happened to Leeds, or did he burn them out?\""),
    (2, "Who are Leeds United's fiercest rivals?", ["Manchester United", "Sheffield United", "Huddersfield Town"], 0,
     "Manchester United, in the Roses rivalry, named after the Wars of the Roses, fought five hundred years before football.",
     "impress", "\"Leeds and Man United is the Roses rivalry. It goes back to an actual war in the 1400s.\""),
    (3, "Which captain of the 1969 and 1974 title teams has a statue outside the ground?", ["Billy Bremner", "Jack Charlton", "Johnny Giles"], 0,
     "Billy Bremner, the small, red-haired Scottish midfielder who was afraid of nobody. The statue went up in 1999.",
     "say", "\"That's Billy Bremner. The old captain. Tiny and terrifying.\""),
    (2, "Which old Leeds nickname came from a pub near the ground?", ["The Peacocks", "The Blades", "The Owls"], 0,
     "The Peacocks, after the Old Peacock pub across the road from the ground. The Blades and the Owls are the two Sheffield clubs.",
     "impress", "\"Leeds used to be called the Peacocks, after a pub by the ground. Hardly anyone says it now.\""),
    (2, "Why did Leeds switch to their famous kit in 1961?", ["To copy Real Madrid", "Sponsors demanded it", "To match the city's coat of arms"], 0,
     "The new manager changed it to copy Real Madrid, winners of the first five European Cups, hoping his players would carry themselves like champions.",
     "say", "\"They changed the kit to copy Real Madrid. Then they started winning.\""),
    (3, 'Leeds lost the 1975 European Cup final to which club?', ['Bayern Munich', 'Ajax', 'Juventus'], 0,
     'Bayern Munich, 2-0 in Paris, after a Leeds goal was ruled out and two penalty shouts refused. Fans rioted and Leeds were banned from Europe.',
     'ask', '"Paris 1975. Were Leeds robbed, honestly?"'),
    (3, "Leeds returned to the Premier League in 2025 as Championship champions with how many points?", ["90", "95", "100"], 2,
     "One hundred, level with Burnley, decided on the final day. Both went up, and Leeds took the title on goal difference.",
     "say", "\"A hundred points and it came down to goal difference on the final day.\""),
    (2, "What is the name of the Leeds United club song?", ["Marching On Together", "Glory Glory Leeds", "Yorkshire Forever"], 0,
     "Marching On Together, released as a single for the 1972 FA Cup final and sung at every game since. The words are on the wall outside the ground.",
     "say", "\"Marching On Together. That's the one they all sing.\""),
    (3, "Leeds won the FA Cup in 1972 by beating which club?", ["Arsenal", "Chelsea", "Sunderland"], 0,
     "Arsenal, 1-0 in the centenary final, with an Allan Clarke diving header. By 2026 it was the club's one FA Cup win.",
     "impress", "\"Leeds won the FA Cup in 1972. The centenary final, with a diving header.\""),
    (1, "Leeds is in which county?", ["Yorkshire", "Lancashire", "Derbyshire"], 0,
     "West Yorkshire. The white rose on the badge is the county's symbol.",
     "say", "\"Yorkshire. Don't say 'up north' to a Leeds fan, say Yorkshire.\""),
    (3, "Which player did Leeds sell to Manchester United in the 1990s, a deal they came to regret?", ["Eric Cantona", "Lee Chapman", "David Batty"], 0,
     "Eric Cantona, in November 1992, for about £1.2 million. He won four titles in five years at Old Trafford.",
     "impress", "\"Leeds sold Cantona to Man United for about a million. Then he won four titles for them.\""),
    (2, "Which German manager led Leeds to promotion in 2025?", ["Daniel Farke", "Jesse Marsch", "Thomas Tuchel"], 0,
     "Daniel Farke, who had already taken Norwich up twice, in 2019 and 2021. He knew the Championship inside out.",
     "ask", "\"Was Farke the man for the Premier League, or just brilliant in the Championship?\""),
]

LIVERPOOL = [
    (1, "What is Liverpool's home ground called?", ["Anfield", "Goodison Park", "Stanley Park"], 0,
     "Anfield, since 1892. It was Everton's ground first, until a rent row saw Everton leave and the landlord start a new club to play there.",
     "impress", "\"Liverpool were founded because Everton fell out with their landlord over rent at Anfield.\""),
    (1, "Which song do Liverpool fans sing before every home match?", ["You'll Never Walk Alone", "Blue Moon", "Marching On Together"], 0,
     "You'll Never Walk Alone, a show tune from the musical Carousel, adopted in 1963 after a Liverpool band had a hit with it. The words are on the gates at the ground.",
     "impress", "\"You'll Never Walk Alone is from a musical. Carousel, 1945. They took it from a pop cover.\""),
    (2, "Liverpool's league title in 2025 was the club's how-manyth?", ["Eighteenth", "Nineteenth", "Twentieth"], 2,
     "Twentieth, drawing level with Manchester United. The nineteenth had ended a thirty-year wait.",
     "say", "\"Twenty titles by 2025. Level with United. That's the argument at every family dinner.\""),
    (2, "How many times had Liverpool won the European Cup or Champions League by 2025?", ["Four", "Five", "Six"], 2,
     "Six: 1977, 1978, 1981, 1984, 2005 and 2019. By 2025 no other English club had as many, which Liverpool fans mention regularly.",
     "say", "\"Six European Cups. Ask a United fan how many they've got.\""),
    (1, 'Liverpool came back from 3-0 down to win the 2005 Champions League final against which club?', ['AC Milan', 'Juventus', 'Real Madrid'], 0,
     'AC Milan, in Istanbul: 3-0 down at half-time, three goals in six minutes early in the second half, then won on penalties. The miracle of Istanbul.',
     'ask', '"Istanbul 2005. Where were you at half-time?"'),
    (1, "Which German managed Liverpool from 2015 to 2024?", ["Jürgen Klopp", "Thomas Tuchel", "Ralf Rangnick"], 0,
     "Jürgen Klopp: hugs, heavy-metal football, a Champions League and a league title after thirty years. He left as one of the best-loved managers the club had known.",
     "say", "\"Klopp. Nine years, everyone loved him, then he just left on his own terms.\""),
    (2, "In which year did Liverpool end their thirty-year wait for a league title?", ["2019", "2020", "2022"], 1,
     "2020, during the pandemic, with seven games to spare and an empty stadium. Fans celebrated outside the ground anyway.",
     "ask", "\"Winning it in lockdown with no fans in. Did it feel real?\""),
    (3, "Which striker scored 346 goals for Liverpool across two spells in the 1980s and 90s?", ["Ian Rush", "Roger Hunt", "Robbie Fowler"], 0,
     "Ian Rush, a Welsh striker with a moustache and a knack for scoring against Everton. By 2025 nobody had scored more for the club.",
     "ask", "\"Will anyone ever catch Ian Rush's 346?\""),
    (1, "Which two clubs are Liverpool's main rivals?", ["Everton and Man United", "Everton and Leeds", "Manchester City and Chelsea"], 0,
     "Everton, across the park, in the Merseyside derby; and Manchester United, thirty miles away, a rivalry built on decades of fighting over trophies.",
     "say", "\"Everton's the local one. United's the real one.\""),
    (3, "The Kop, Anfield's famous stand, is named after what?", ["A hill in the Boer War", "A Liverpool docker", "A Norwegian word for stand"], 0,
     "Spion Kop, a hill in South Africa where many soldiers from Liverpool died in a battle in 1900. The steep terrace reminded people of it.",
     "impress", "\"The Kop's named after a hill in the Boer War where Liverpool soldiers died.\""),
    (2, "Which Scot managed Liverpool from 1959 to 1974 and has a statue outside Anfield?", ["Bill Shankly", "Bob Paisley", "Kenny Dalglish"], 0,
     "Bill Shankly, who took them up from the second division and built the modern club. The Shankly Gates went up in his honour in 1982, and his quotes turn up everywhere.",
     "say", "\"Shankly said football's more important than life and death. He was joking. Mostly.\""),
    (3, 'Which Liverpool manager won three European Cups between 1977 and 1981?', ['Bob Paisley', 'Joe Fagan', 'Kenny Dalglish'], 0,
     'Bob Paisley, the quiet assistant who stepped up in 1974 and turned out to be even more successful: six league titles and three European Cups in nine years.',
     'impress', '"Paisley won three European Cups. Nobody talks about him because he didn\'t do quotes."'),
    (3, "Steven Gerrard's long-range equaliser in the 2006 FA Cup final came against which club?", ["West Ham", "Chelsea", "Arsenal"], 0,
     "West Ham, in the final minute, from 35 yards, with cramp. Liverpool won on penalties. People call it the Gerrard final.",
     "say", "\"The Gerrard final. Thirty-five yards, last minute, cramp in both legs.\""),
    (2, "Mohamed Salah joined Liverpool in 2017 from which club?", ["Roma", "Chelsea", "Fiorentina"], 0,
     "Roma, for about £37 million, after Chelsea had given up on him. He scored 44 goals in his first season.",
     "ask", "\"Is Salah the best signing Liverpool have ever made?\""),
    (3, "Virgil van Dijk joined Liverpool in 2018 from which club?", ["Southampton", "Celtic", "Ajax"], 0,
     "Southampton, for £75 million, a world record for a defender at the time. Liverpool reached the next two Champions League finals with him.",
     "say", "\"Seventy-five million for a defender looked mad. Then they won everything.\""),
    (2, "Who took over at Liverpool in 2024 and won the title in his first season?", ["Arne Slot", "Xabi Alonso", "Ruben Amorim"], 0,
     "Arne Slot, from Feyenoord. Calm where his predecessor was loud, and champion within a year.",
     "ask", "\"Did Slot win that title, or was it the team he inherited?\""),
    (2, "Who did Liverpool beat in the 2019 Champions League final?", ["Tottenham Hotspur", "Manchester City", "Real Madrid"], 0,
     "Tottenham, 2-0 in Madrid, with a penalty in the second minute, a year after losing the final to Real Madrid.",
     "say", "\"Madrid 2019. Penalty in the second minute and that was that.\""),
    (3, "In the 2019 comeback against Barcelona, who took the quick corner for the winning goal?", ["Trent Alexander-Arnold", "Alex Oxlade-Chamberlain", "Xherdan Shaqiri"], 0,
     "Trent Alexander-Arnold, a local lad, while Barcelona's defenders were not looking. Divock Origi tapped it in to complete a 4-0 win from 3-0 down.",
     "impress", "\"'Corner taken quickly, Origi.' That's the commentary from the Barcelona game. Fans quote it.\""),
    (1, "What bird is on the Liverpool badge?", ["The liver bird", "A magpie", "A cockerel"], 0,
     "The liver bird, the city's symbol, a cormorant with a sprig of seaweed in its beak. It is on the town hall and the Liver Building too.",
     "say", "\"That's the liver bird. It's all over the city, not just the club.\""),
    (3, "Kenny Dalglish joined Liverpool in 1977 from which club?", ["Celtic", "Rangers", "Aberdeen"], 0,
     "Celtic, for £440,000, to replace Kevin Keegan. He became a club great, then its manager, and won the league in both roles.",
     "say", "\"King Kenny. Player, manager, won the league as both. There's a stand named after him.\""),
]

MAN_CITY = [
    (1, "What is Manchester City's home ground called?", ["Etihad Stadium", "Old Trafford", "Emirates Stadium"], 0,
     "The Etihad Stadium, built for the 2002 Commonwealth Games and converted for football. Officially the City of Manchester Stadium.",
     "say", "\"The Etihad was built for the Commonwealth Games. City moved in after.\""),
    (2, "Where did Manchester City play before they moved grounds in 2003?", ["Maine Road", "Hyde Road", "Old Trafford"], 0,
     "Maine Road, in Moss Side, from 1923 to 2003. In 1934 it held 84,569 for an FA Cup game against Stoke.",
     "ask", "\"Did you ever go to Maine Road? Everyone says it was a different club then.\""),
    (1, "What colour are Manchester City's home shirts?", ["Sky blue", "Red", "Navy blue"], 0,
     "Sky blue, since the 1890s. The fans' song is Blue Moon, sung slowly and sadly, which suited the club for much of its history.",
     "say", "\"Blue Moon. They sing it slow, from when City were rubbish. It stuck.\""),
    (1, "Which Spanish manager took charge of Manchester City in 2016?", ["Pep Guardiola", "Roberto Mancini", "Mikel Arteta"], 0,
     "Pep Guardiola, who had won everything at Barcelona and Bayern. Six league titles in his first eight seasons at City and a treble in 2023.",
     "ask", "\"Is Guardiola the best manager there's ever been, or did the money do it?\""),
    (2, "In which year was Manchester City bought by Abu Dhabi's Sheikh Mansour?", ["2003", "2008", "2012"], 1,
     "2008, on the final day of the transfer window. They signed Robinho the same afternoon and the modern City began.",
     "say", "\"2008. Before that they were a joke club. After that, well.\""),
    (2, "In which year did Manchester City win their first Premier League title?", ["2010", "2012", "2014"], 1,
     "2012, with Agüero's goal in the final seconds of the final game against QPR, to beat United on goal difference. Their first title since 1968.",
     "say", "\"Agüerooo. Last kick of the season. Even neutrals remember where they were.\""),
    (2, "Which English club won the league, FA Cup and European Cup treble before City did in 2023?", ["Manchester United", "Liverpool", "Nottingham Forest"], 0,
     "Manchester United, in 1999, under Alex Ferguson. City matching United's treble was a big part of the joy.",
     "say", "\"2023 treble. United had done it in 1999, and City loved matching it.\""),
    (2, "Who did Manchester City beat in the 2023 Champions League final?", ["Inter Milan", "Real Madrid", "Bayern Munich"], 0,
     "Inter Milan, 1-0 in Istanbul, with a goal from Rodri. Their first European Cup, after years of trying.",
     "say", "\"Rodri scored the goal in Istanbul. First European Cup, finally.\""),
    (2, "How many goals did Erling Haaland score in the 2022-23 Premier League season?", ["34", "36", "40"], 1,
     "Thirty-six, in his first season in England, beating a mark that had stood since 1994. Also 52 in all competitions.",
     "say", "\"Thirty-six league goals in his first season. In England. At 22.\""),
    (2, "In 2024 City became the first English club to win how many consecutive league titles?", ["Three", "Four", "Five"], 1,
     "Four in a row, 2021 to 2024. Nobody had done more than three before.",
     "impress", "\"Four titles in a row. Nobody had ever done that in England.\""),
    (2, "What did Alex Ferguson call City in 2009, after the money arrived?", ["The noisy neighbours", "The poor relations", "The small club down the road"], 0,
     "The noisy neighbours, a jibe from United's manager once City started spending big. City fans took it as a compliment.",
     "say", "\"The noisy neighbours. Ferguson's line. Aged badly for him.\""),
    (3, "In the 1999 play-off final against Gillingham, who scored City's 95th-minute equaliser?", ["Paul Dickov", "Shaun Goater", "Kevin Horlock"], 0,
     "Paul Dickov, at Wembley, with City 2-0 down and in the third tier. They won on penalties. Fans talk about it as the goal that saved the club.",
     "impress", "\"City were in the third division in 1999. Hard to believe now, isn't it?\""),
    (3, "In which year did Manchester City win the European Cup Winners' Cup?", ["1956", "1970", "1976"], 1,
     "1970, beating Górnik Zabrze of Poland in Vienna. Their one European trophy until 2023.",
     "impress", "\"City won a European trophy in 1970 and then nothing in Europe until 2023.\""),
    (3, "The Colin Bell Stand at City's ground is named after a 1960s midfielder nicknamed what?", ["Nijinsky", "The King", "The Engine"], 0,
     "Nijinsky, after a famous racehorse, because he could run all day. A stand is named after him, the sign of a true club great.",
     "impress", "\"Colin Bell was nicknamed after a racehorse. Nijinsky. Because he ran all day.\""),
    (3, "Which Spanish playmaker, nicknamed El Mago, has a statue outside City's ground?", ["David Silva", "Sergio Agüero", "Vincent Kompany"], 0,
     "David Silva, the magician, ten seasons and four titles, with a statue alongside Agüero's and Kompany's. Small, left-footed, impossible to tackle.",
     "say", "\"Silva, Agüero, Kompany. The three statues. That's the team that started it.\""),
    (2, "In which year did Manchester City beat Manchester United 6-1 at Old Trafford?", ["2011", "2014", "2019"], 0,
     "2011, in October. Balotelli scored and lifted his shirt to reveal the words 'Why always me?'",
     "say", "\"Six-one at Old Trafford. 'Why always me?' That whole day was ridiculous.\""),
    (2, "What is Manchester City's nickname?", ["The Citizens", "The Moonrakers", "The Mancs"], 0,
     "The Citizens, though fans mostly just say City. Cityzens, with a z, is what the club calls its members.",
     "say", "\"City. Nobody actually says the Citizens.\""),
    (2, "What did many fans call City's new ground at first, after the area it was built in?", ["Eastlands", "Salford Quays", "Didsbury"], 0,
     "Eastlands, old industrial land in east Manchester that was rebuilt around the stadium, with a training campus and an arena added later.",
     "say", "\"People used to call it Eastlands. East Manchester, all rebuilt around the ground.\""),
    (3, "Which Chilean manager won the Premier League with Manchester City in 2014?", ["Manuel Pellegrini", "Roberto Mancini", "Mark Hughes"], 0,
     "Manuel Pellegrini, the first manager from outside Europe to win the Premier League. Quiet, polite, and gone by 2016.",
     "impress", "\"Pellegrini won City a title in 2014 and nobody ever mentions him. First non-European to win it.\""),
    (3, "In which year did Manchester City win their first league title?", ["1904", "1937", "1968"], 1,
     "1937. They were relegated the very next season while scoring more goals than anyone in the division. 'Typical City', fans said for decades.",
     "impress", "\"City won the league in 1937 and got relegated the next year. That's where 'typical City' comes from.\""),
]

